// Description: Java 25 Private Security Service Interface.

$MssSourceLicense$

package $reference ManufacturingSchema lower JavaPackage$.$reference ManufacturingSchema lower SchemaName$;

import server.markhome.cf.dbutil.*;
import server.markhome.cf.CFDbKeyHash256;
import $reference ManufacturingSchema lower JavaPackage$.$reference ManufacturingSchema lower SchemaName$pub.I$SchemaName$PubSecurityService;
import $reference ManufacturingSchema lower JavaPackage$.$reference ManufacturingSchema lower SchemaName$prot.I$SchemaName$ProtSecurityService;
import $reference ManufacturingSchema lower JavaPackage$.$reference ManufacturingSchema lower SchemaName$prot.I$SchemaName$ProtSecurityControl;

/*
 *	An I$SchemaName$SecurityService is the private service interface used in
 *	application server code to implement a SecurityService cache that can accept new
 *	server registrations.
 *	The I$SchemaName$SecurityControl interface is a private interface used by the
 *	security server to control security server caches that have registered interest
 *	in the security server. The control interface is used to communicate between the
 *	root security server and the security server caches.
 */
public interface I$SchemaName$SecurityService extends I$SchemaName$ProtSecurityService {

	/**
	 *	Register a SecurityControl implementation as an interested listener to receive propagation of the forget commands filtered by their
	 *	intersection with information in this cache.
	 *
	 *	@param securityControl If you can't control it, you can't register it.
	 *
	 *	@return true if a new interest registration was established, false if the interest had been previously established.
	 */
	public default boolean registerInterest(I$SchemaName$SecurityControl securityControl) {
		return registerInterest((I$SchemaName$ProtSecurityControl)securityControl);
	};

	/**
	 *	Remove a SecurityControl implementation from the registered list of listeners.
	 *
	 *	@param securityControl If you can't control it, you can't register it.
	 *
	 *	@return true if the security control was removed, false if it was not found.
	 */
	public default boolean forgetInterest(I$SchemaName$SecurityControl securityControl) {
		return forgetInterest((I$SchemaName$ProtSecurityControl)securityControl);
	};

	/**
	 *	Did the specified SecurityControl register interest in filtered forget commands?
	 *
	 *	@param securityControl If you can't control it, you can't register it.
	 *
	 *	@return true if the SecurityControl is in the interest registration list, otherwise false.
	 */
	public default boolean isInterested(I$SchemaName$SecurityControl securityControl) {
		return isInterested((I$SchemaName$ProtSecurityControl)securityControl);
	};
}
